CREATE TABLE analytics.metrics_agg (
  k UInt8,
  total_st AggregateFunction(count),
  users_st AggregateFunction(uniq, String),
  revenue_st AggregateFunction(sum, Float64)
) ENGINE = AggregatingMergeTree()
ORDER BY k;

CREATE TABLE analytics.events_by_region_day (
  region String,
  day Date,
  cnt UInt64
) ENGINE = SummingMergeTree()
ORDER BY (region, day);

INSERT INTO analytics.metrics_agg
SELECT
  toUInt8(1) AS k,
  countState() AS total_st,
  uniqState(user_id) AS users_st,
  sumState(revenue) AS revenue_st
FROM analytics.events
GROUP BY k;

INSERT INTO analytics.events_by_region_day
SELECT
  region,
  toDate(event_ts) AS day,
  count() AS cnt
FROM analytics.events
GROUP BY region, day;

CREATE MATERIALIZED VIEW analytics.metrics_agg_mv TO analytics.metrics_agg AS
SELECT
  toUInt8(1) AS k,
  countState() AS total_st,
  uniqState(user_id) AS users_st,
  sumState(revenue) AS revenue_st
FROM analytics.events
GROUP BY k;

CREATE MATERIALIZED VIEW analytics.events_by_region_day_mv TO analytics.events_by_region_day AS
SELECT
  region,
  toDate(event_ts) AS day,
  count() AS cnt
FROM analytics.events
GROUP BY region, day;
"

